"import os


def w(path, text):
    directory = os.path.dirname(path)
    if directory:
        os.makedirs(directory, exist_ok=True)
    with open(path, "w", encoding="utf-8") as file:
        file.write(text)


def field(name, field_class, dimensions, internal_field, boundary_field):
    header = (
        "FoamFile { format ascii; class "
        + field_class
        + "; object "
        + name
        + '; location "0/'
        + name
        + '"; }'
    )
    return (
        header
        + "\ndimensions "
        + dimensions
        + ";\ninternalField uniform "
        + internal_field
        + ";\nboundaryField\n{\n"
        + boundary_field
        + "\n}\n"
    )


